<script setup lang="ts">
import {useWebSettings,settingsFields} from '../../state/web-settings.ts';
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import PdfReader from './PdfReader.vue';
import {vResizablePanels} from '../../layout/resizablePanels.ts';
import AppIcon from '../../components/AppIcon.vue';
import {citation,citationStyles,type CitationStyle} from './citations.ts';
import {copyText} from '../../platform/clipboard.ts';
import ModalDialog from '../../components/ModalDialog.vue';
import {pageScale} from '../../state/pageZoom.ts';
import {papers as desktopPapers,papersAvailable,missing,bytesLabel,onPaperStatus,type PaperStatus,type Paper,type PaperLanguage,type LocalLibrary,type PapersClient} from '../../platform/papers.ts';
const props=defineProps<{active?:boolean;port?:PapersClient;stateKey?:string}>();const emit=defineEmits<{help:[]}>();
const papers:PapersClient=props.port??desktopPapers;const available=()=>!!props.port||papersAvailable();
const state=ref<PaperStatus>({firstLaunch:'',warning:'',papers:[]});
const local=ref<LocalLibrary>({root:'',folders:[],documents:[]});
const source=ref<'server'|'local'>('server'),serverSelected=ref(''),localSelected=ref('');
const details=ref(false),citeOpen=ref(false),citeStyle=ref<CitationStyle>('GB/T 7714—2015'),copyNotice=ref('');
const language=ref<PaperLanguage>('original'),page=ref(1),search=ref(''),period=ref(''),folder=ref('*');
const busy=ref(false),settingsBusy=ref(false),error=ref(''),progress=ref(''),notice=ref('');
const interval=ref(6),settingsInterval=ref(6),settingsOpen=ref(false),historical=ref(false),archivePeriod=ref(''),chosen=ref<string[]>([]),showObtained=ref(false);
const folderOpen=ref(false),folderName=ref(''),moveOpen=ref(false),destinationFolder=ref(''),importOpen=ref(false);
const trashOpen=ref(false),trashItems=ref<{id:string;title:string}[]>([]);
async function openTrash(){await action(async()=>{trashItems.value=await papers.trash!();trashOpen.value=true;});}
async function restoreTrash(id:string){await action(async()=>{applyLocal(await papers.restoreLocal!(id));trashItems.value=await papers.trash!();notice.value='PDF 已恢复，原有批注保留。';});}
const deleteTarget=ref<{source:'server'|'local';folder:string}|null>(null);
const paperMenu=ref<{source:'server'|'local';id:string;title:string;notice?:boolean;x:number;y:number}|null>(null),menuElement=ref<HTMLElement>();
const deletePaperTarget=ref<{source:'server'|'local';id:string;title:string;notice?:boolean}|null>(null);
const today=ref(new Date().toLocaleDateString('sv-SE'));
const selected=computed(()=>source.value==='server'?serverSelected.value:localSelected.value);
const availableNotice=computed(()=>state.value.notice&&!state.value.notice.dismissed?state.value.notice:undefined);
const serverPapers=computed(()=>state.value.papers.filter(p=>!p.dismissed&&p.publishedAt<=today.value&&(p.downloaded||p.acquired||p.publishedAt>=state.value.firstLaunch||(p.updatedAt??'')>=state.value.firstLaunch)).sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt)||a.title.localeCompare(b.title)));
const sourceItems=computed(()=>source.value==='server'?serverPapers.value:local.value.documents);
const years=computed(()=>[...new Set(sourceItems.value.map(p=>p.publishedAt.slice(0,4)))].sort().reverse());
const months=computed(()=>[...new Set(sourceItems.value.filter(p=>!period.value||p.publishedAt.startsWith(period.value.slice(0,4))).map(p=>p.publishedAt.slice(0,7)))].sort().reverse());
const folders=computed(()=>source.value==='server'?state.value.folders??[]:local.value.folders);
const visible=computed(()=>sourceItems.value.filter(p=>(!period.value||p.publishedAt.startsWith(period.value))&&(!search.value||`${p.title} ${p.titleZh}`.toLowerCase().includes(search.value.toLowerCase()))&&(folder.value==='*'||(source.value==='local'?('folder' in p?p.folder:''):(state.value.collections?.[p.id]??''))===folder.value)));
const current=computed<Paper|undefined>(()=>{
 if(source.value==='server')return availableNotice.value?.id===serverSelected.value?availableNotice.value:serverPapers.value.find(p=>p.id===serverSelected.value);
 const p=local.value.documents.find(p=>p.id===localSelected.value);if(!p)return;
 const asset={path:'',size:p.size,sha256:''};return {...p,local:true,authors:'',version:'本地 PDF',sourceUrl:'',submittedAt:p.publishedAt,license:{id:'个人文件',url:''},translationNote:'',guide:'',original:asset,translation:asset,downloaded:true};
});
const archive=computed(()=>[...(state.value.notice?[state.value.notice]:[]),...state.value.papers].filter(p=>p.publishedAt<=today.value).sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt)));
const archiveYears=computed(()=>[...new Set(archive.value.map(p=>p.publishedAt.slice(0,4)))].sort().reverse());
const archiveMonths=computed(()=>[...new Set(archive.value.map(p=>p.publishedAt.slice(0,7)))].sort().reverse());
const archivePapers=computed(()=>archive.value.filter(p=>!archivePeriod.value||p.publishedAt.startsWith(archivePeriod.value)));
const pendingPapers=computed(()=>archivePapers.value.filter(p=>!p.downloaded));
const selectedPapers=computed(()=>archive.value.filter(p=>!p.downloaded&&chosen.value.includes(p.id)));
const allChecked=computed(()=>pendingPapers.value.length>0&&pendingPapers.value.every(p=>chosen.value.includes(p.id)));
const downloadBytes=computed(()=>selectedPapers.value.reduce((n,p)=>n+p.original.size+(p.notice?0:p.translation.size+(p.analysisPdf?.size??0)),0));
const citationText=computed(()=>current.value?citation(current.value,citeStyle.value,today.value):'');
const readerKey=computed(()=>current.value?[current.value.id,current.value.original.sha256,current.value.translation.sha256,current.value.analysisPdf?.sha256??''].join(':'):'');
let controller:AbortController|undefined;let stopMaintenance:(()=>void)|undefined;
const positions=new Map<string,number>();const unsubscribe=(papers.onStatus??onPaperStatus)(apply);
function apply(value:PaperStatus){state.value=value;interval.value=value.checkIntervalHours??6;if(!serverSelected.value||(!serverPapers.value.some(p=>p.id===serverSelected.value)&&availableNotice.value?.id!==serverSelected.value))serverSelected.value=availableNotice.value?.id??serverPapers.value[0]?.id??'';chosen.value=chosen.value.filter(id=>archive.value.some(p=>p.id===id&&!p.downloaded));}
function applyLocal(value:LocalLibrary){if(value.cancelled)return;local.value=value;if(value.selected)localSelected.value=value.selected;else if(value.imported?.length)localSelected.value=value.imported[0];else if(!value.documents.some(p=>p.id===localSelected.value))localSelected.value=value.documents[0]?.id??'';if(value.failures?.length)error.value=value.failures.join('\n');}
watch(selected,()=>{if(current.value?.notice||current.value?.local)language.value='original';page.value=positions.get(selected.value+':'+language.value)??1;details.value=false;});
watch(source,()=>{search.value='';period.value='';folder.value='*';language.value='original';});
function changeLanguage(value:PaperLanguage){language.value=value;page.value=positions.get(selected.value+':'+value)??1;}
function remember(value:number){page.value=value;positions.set(selected.value+':'+language.value,value);}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;progress.value='';}}
async function getPapers(ids:string[]){await action(async()=>{controller=new AbortController();try{apply(await papers.downloadSelected(ids,controller.signal,p=>{progress.value=`正在获取 ${bytesLabel(p.received)} / ${bytesLabel(p.total)}`;}));}catch(e){try{apply(await papers.status());}catch{}throw e;}});}
async function refresh(){await action(async()=>{const acquired=new Set(state.value.papers.filter(p=>p.acquired||p.downloaded).map(p=>p.id));today.value=new Date().toLocaleDateString('sv-SE');controller=new AbortController();apply(await papers.refresh(controller.signal));const ids=missing(state.value.papers,state.value.firstLaunch,today.value).map(p=>p.id);if(ids.length){apply(await papers.downloadSelected(ids,controller.signal,p=>{progress.value=`正在获取 ${bytesLabel(p.received)} / ${bytesLabel(p.total)}`;}));const added=ids.filter(id=>!acquired.has(id)).length,updated=ids.length-added;notice.value=[added?`已获取 ${added} 篇新论文。`:'',updated?`已更新 ${updated} 篇已有论文的内容。`:''].filter(Boolean).join(' ');}else notice.value=`服务器目录共 ${state.value.papers.length} 篇，本次检查无需下载。`;});}
async function history(){historical.value=true;archivePeriod.value=archiveYears.value[0]??'';chosen.value=[];showObtained.value=false;await action(async()=>{controller=new AbortController();apply(await papers.refresh(controller.signal));archivePeriod.value=archiveYears.value[0]??'';});}
function selectAll(){const ids=new Set(chosen.value);for(const p of pendingPapers.value){if(allChecked.value)ids.delete(p.id);else ids.add(p.id);}chosen.value=[...ids];}
async function autoCheck(event:Event){settingsBusy.value=true;error.value='';try{apply(await papers.setAutoReceive((event.target as HTMLInputElement).checked));}catch(e){error.value=(e as Error).message;}finally{settingsBusy.value=false;}}
async function saveInterval(){settingsBusy.value=true;error.value='';try{apply(await papers.setInterval(settingsInterval.value));notice.value='自动检查间隔已保存。';settingsOpen.value=false;}catch(e){error.value=(e as Error).message;}finally{settingsBusy.value=false;}}
async function chooseRoot(){await action(async()=>applyLocal(await papers.chooseLibrary()));}
async function refreshLocal(){await action(async()=>applyLocal(await papers.library()));}
function prepareImport(){destinationFolder.value=folder.value==='*'?'':folder.value;importOpen.value=true;}
async function importPdfs(){await action(async()=>{const result=await papers.importLocal(destinationFolder.value);if(result.cancelled)return;applyLocal(result);importOpen.value=false;folder.value='*';period.value='';search.value='';notice.value=`已导入 ${result.imported?.length??0} 份 PDF。`;});}
async function createFolder(){await action(async()=>{if(source.value==='local')applyLocal(await papers.createFolder(folderName.value));else apply(await papers.createRecommendationFolder(folderName.value));folderOpen.value=false;folderName.value='';});}
function prepareDelete(){if(folder.value&&folder.value!=='*')deleteTarget.value={source:source.value,folder:folder.value};error.value='';}
async function deleteFolder(){const target=deleteTarget.value;if(!target)return;await action(async()=>{if(target.source==='local'){const result=await papers.deleteFolder(target.folder);for(const [oldId,newId] of Object.entries(result.relocated??{})){const saved=positions.get(oldId+':original');if(saved!==undefined)positions.set(newId+':original',saved);if(localSelected.value===oldId){positions.set(newId+':original',page.value);localSelected.value=newId;}}applyLocal(result);folder.value=target.folder.split('/').slice(0,-1).join('/');notice.value='收藏夹已删除，内部文件和子文件夹已移到上一级。';}else{apply(await papers.deleteRecommendationFolder(target.folder));folder.value='';notice.value='收藏夹已删除，论文及批注保留，现归入未收藏。';}deleteTarget.value=null;});}
function prepareMove(){destinationFolder.value=source.value==='local'?(local.value.documents.find(p=>p.id===selected.value)?.folder??''):(state.value.collections?.[selected.value]??'');moveOpen.value=true;}
async function move(){await action(async()=>{if(source.value==='local'){const old=selected.value;const result=await papers.moveLocal(old,destinationFolder.value);if(result.selected)positions.set(result.selected+':original',page.value);applyLocal(result);}else apply(await papers.collectRecommendation(selected.value,destinationFolder.value));folder.value='*';moveOpen.value=false;notice.value=source.value==='local'?'PDF 已整理到所选文件夹。':'已加入所选收藏夹。';});}
async function copyCitation(){try{await copyText(citationText.value);copyNotice.value='已复制引用。';}catch(e){copyNotice.value=(e as Error).message;}}
function openPaperMenu(event:MouseEvent,p:{id:string;titleZh:string;notice?:boolean}){if(busy.value)return;source.value==='server'?serverSelected.value=p.id:localSelected.value=p.id;const scale=pageScale.value/100;paperMenu.value={source:source.value,id:p.id,title:p.titleZh,notice:p.notice,x:Math.max(6,Math.min(event.clientX,window.innerWidth-215))/scale,y:Math.max(6,Math.min(event.clientY,window.innerHeight-55))/scale};nextTick(()=>menuElement.value?.querySelector('button')?.focus());}
function paperMenuKey(event:KeyboardEvent,p:{id:string;titleZh:string;notice?:boolean}){const r=(event.currentTarget as HTMLElement).getBoundingClientRect();openPaperMenu({clientX:r.left+25,clientY:r.bottom} as MouseEvent,p);}
function closePaperMenu(event:PointerEvent){if(!(event.target as HTMLElement)?.closest('.paper-context'))paperMenu.value=null;}
function escapePaperMenu(event:KeyboardEvent){if(event.key==='Escape')paperMenu.value=null;}
function preparePaperDelete(){if(paperMenu.value)deletePaperTarget.value={...paperMenu.value};paperMenu.value=null;error.value='';}
async function deletePaper(){const target=deletePaperTarget.value;if(!target)return;await action(async()=>{if(target.source==='server'){apply(await papers.removeDownload(target.id));serverSelected.value=availableNotice.value?.id??visible.value[0]?.id??'';notice.value=target.notice?'栏目说明已删除，批注保留。可从获取往期重新获取。':'本机论文副本已删除，批注保留。可从获取往期重新选择下载。';}else{applyLocal(await papers.removeLocal(target.id));notice.value='库内 PDF 已移入回收站，批注与原导入来源保留。';}deletePaperTarget.value=null;});}
watch(()=>props.active,active=>{if(!active)paperMenu.value=null;});
onMounted(async()=>{if(!available())return;try{apply(await papers.status());try{applyLocal(await papers.library());stopMaintenance=papers.maintain?.();}catch(e){error.value=(e as Error).message;}}catch(e){error.value=(e as Error).message;}});
onMounted(()=>{document.addEventListener('pointerdown',closePaperMenu,true);document.addEventListener('keydown',escapePaperMenu);});
onBeforeUnmount(()=>{controller?.abort();stopMaintenance?.();unsubscribe();document.removeEventListener('pointerdown',closePaperMenu,true);document.removeEventListener('keydown',escapePaperMenu);});
useWebSettings(props.stateKey,{citeStyle,language,details,showObtained});
</script>
<template>
<section class="paper-reading" aria-label="语音学论文精读">
 <header class="paper-heading">
  <div class="source-tabs" role="tablist" aria-label="论文来源"><button role="tab" :aria-selected="source==='server'" :class="{selected:source==='server'}" @click="source='server'">服务器推荐 <small>{{serverPapers.length}}</small></button><button role="tab" :aria-selected="source==='local'" :class="{selected:source==='local'}" @click="source='local'">我的 PDF <small>{{local.documents.length}}</small></button></div>
  <div class="paper-actions" v-if="source==='server'"><label class="auto-switch"><input type="checkbox" :checked="state.autoReceive!==false" :disabled="settingsBusy||!available()" @change="autoCheck">自动获取</label><button class="interval-button" :title="state.autoReceive===false?'已关闭自动检查':`应用启动时检查，此后每 ${interval} 小时检查`" :disabled="!available()" @click="settingsInterval=interval;settingsOpen=true">{{interval}} 小时</button><button :disabled="busy||!available()" @click="history">获取往期</button><button :disabled="busy||!available()" @click="refresh">检查新论文</button><button @click="emit('help')">帮助</button></div>
  <div class="paper-actions" v-else><button :disabled="busy||!available()" @click="chooseRoot">{{papers.web?(local.root?'导入其他文件夹':'导入论文文件夹'):(local.root?'更换文件夹':'选择论文文件夹')}}</button><button :disabled="busy||!local.root" @click="refreshLocal">刷新</button><button class="primary" :disabled="busy||!local.root" @click="prepareImport">导入 PDF</button><button v-if="papers.web" :disabled="busy" @click="openTrash">回收站</button><button @click="emit('help')">帮助</button></div>
 </header>
 <p v-if="!available()" class="paper-notice">请在桌面版使用论文库。推荐内容由服务器分发，个人 PDF 保存在所选本地文件夹。</p>
 <div v-if="busy||error||notice||state.warning" class="paper-notice" role="status"><span>{{error||notice||state.warning||progress||'正在处理…'}}</span><button v-if="busy" @click="controller?.abort()">取消获取</button><button v-else @click="error='';notice='';state.warning=''">收起</button></div>
 <div class="paper-body" v-resizable-panels="{key:'M18:library',center:'.paper-reader,.paper-empty',centerMin:440,panels:[{selector:'.paper-library',side:'left',label:'论文库',initial:250,min:190,max:480}]}">
  <aside class="paper-library" aria-label="论文目录">
   <div class="library-tools"><input v-model="search" aria-label="搜索论文" type="search" placeholder="搜索题名…"><div class="library-filter"><select aria-label="年份筛选" :value="period.slice(0,4)" @change="period=($event.target as HTMLSelectElement).value"><option value="">全部年份</option><option v-for="year in years" :key="year" :value="year">{{year}} 年</option></select><select aria-label="月份筛选" :value="period.length===7?period:''" @change="period=($event.target as HTMLSelectElement).value||period.slice(0,4)"><option value="">全部月份</option><option v-for="month in months" :key="month" :value="month">{{month.slice(5)}} 月</option></select></div><div class="library-filter"><select v-model="folder" aria-label="收藏夹筛选"><option value="*">全部{{source==='local'?'文件':'推荐'}}</option><option value="">{{source==='local'?'根文件夹':'未收藏'}}</option><option v-for="f in folders" :key="f" :value="f">{{f}}</option></select><button aria-label="新建收藏夹" title="新建收藏夹" :disabled="busy||(source==='local'&&!local.root)||!available()" @click="folderOpen=true">＋</button><button aria-label="删除收藏夹" title="删除收藏夹" :disabled="busy||!folder||folder==='*'||!available()" @click="prepareDelete"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7"/></svg></button></div></div>
   <div class="library-caption"><span>{{source==='server'?'推荐论文':'本地文件'}}</span><small>{{visible.length}} 篇</small></div>
   <div class="paper-list"><button v-if="source==='server'&&availableNotice" class="paper-card paper-intro" :class="{selected:selected===availableNotice.id}" :aria-pressed="selected===availableNotice.id" @click="serverSelected=availableNotice.id;language='original'" @contextmenu.prevent="openPaperMenu($event,availableNotice)" @keydown.shift.f10.prevent="paperMenuKey($event,availableNotice)"><AppIcon class="paper-file-icon" name="info"/><span class="paper-row-title">{{availableNotice.titleZh}}</span><small>栏目说明</small></button><button v-for="p in visible" :key="p.id" class="paper-card" :class="{selected:p.id===selected}" :title="`${p.titleZh}\n${p.title}`" :aria-pressed="p.id===selected" @click="source==='server'?serverSelected=p.id:localSelected=p.id" @contextmenu.prevent="openPaperMenu($event,p)" @keydown.shift.f10.prevent="paperMenuKey($event,p)"><AppIcon class="paper-file-icon" name="file"/><span class="paper-row-title">{{p.titleZh}}</span><small v-if="source==='server'&&'downloaded' in p&&!p.downloaded">↓</small></button><p v-if="!visible.length" class="hint empty-library">{{source==='local'&&!local.root?'选择一个论文文件夹，开始整理自己的 PDF。':'当前筛选下没有论文。'}}</p></div>
   <div class="library-bottom" v-if="source==='local'"><span :title="local.root">{{local.root||'尚未选择文件夹'}}</span><small>{{papers.web?'服务器临时副本 · 导入保留原文件':'收藏夹对应子文件夹 · 导入保留原文件'}}</small></div><div class="library-bottom" v-else><span>{{state.autoReceive===false?'自动获取已关闭':`启动时检查 · 每 ${interval} 小时检查`}}</span><small>默认获取 {{state.firstLaunch||'首次启动'}} 起的推荐</small></div>
  </aside>
  <article v-if="current" class="paper-reader">
   <div class="paper-summary"><button class="paper-fold" :aria-expanded="details" aria-controls="paper-details" @click="details=!details"><span>{{details?'▾':'▸'}}</span><strong :title="current.titleZh">{{current.titleZh}}</strong><small>{{details?'收起信息':'论文信息'}}</small></button><a v-if="!current.local&&!current.notice" :href="current.license.url" target="_blank" rel="noopener noreferrer">{{current.license.id}}</a><button v-if="!current.notice" :disabled="busy" @click="prepareMove">{{current.local?'移至收藏夹':'收藏'}}</button><button v-if="!current.local&&!current.notice" @click="citeOpen=true;copyNotice=''">引用格式</button></div>
   <div v-if="details" id="paper-details" class="paper-details"><div class="paper-metadata"><h2>{{current.titleZh}}</h2><p class="paper-original-title">{{current.title}}</p><template v-if="!current.local&&!current.notice"><small>{{current.authors}} · {{current.version}} · 原稿 {{current.submittedAt}}</small><p class="paper-license"><a :href="current.sourceUrl" target="_blank" rel="noopener noreferrer">原文与版本</a><a :href="current.license.url" target="_blank" rel="noopener noreferrer">{{current.license.id}}</a></p><p class="hint">{{current.translationNote}}</p></template><p v-else-if="current.notice" class="hint">{{current.authors}} · 栏目说明</p><p v-else class="hint">个人 PDF · {{bytesLabel(current.original.size)}} · {{papers.web?'副本随当前工作区保存，请及时导出批注。':'仅保存在所选本地文件夹中，不上传服务器。'}}</p></div><div v-if="!current.local&&!current.notice" class="paper-guide"><strong>阅读导引</strong><p>{{current.guide}}</p><details v-if="current.analysis" class="paper-analysis"><summary>解读与方法分析</summary><p>{{current.analysis}}</p></details></div></div>
   <p v-if="current.acquired&&!current.downloaded" class="paper-notice">原文与译文已获取，新增解读待获取。<button :disabled="busy" @click="getPapers([current.id])">获取解读</button></p>
   <PdfReader :settings-scope="stateKey" :port="papers" v-if="current.downloaded||current.acquired" :key="readerKey" :paper="current" :language="language" :initial-page="page" :active="active" @language="changeLanguage" @position="remember"/>
   <div v-else class="paper-empty"><p>这篇论文还未获取。</p><button class="primary" :disabled="busy" @click="getPapers([current.id])">仅获取这篇论文</button></div>
  </article>
  <div v-else class="paper-empty"><span class="empty-book">▤</span><h2>{{source==='local'?'自己的文献，放在一起':'选一篇论文，慢慢读'}}</h2><p>{{source==='local'?'选择本地文件夹，导入 PDF，用收藏夹整理。':(papers.web?'推荐与个人文件独立管理，批注可随 PDF 导出。':'推荐与个人文件独立管理，获取后可以离线阅读。')}}</p></div>
 </div>
 <ModalDialog v-if="settingsOpen" title="自动检查论文" @close="settingsOpen=false"><p>开启自动获取时，每次打开应用检查一次，持续运行时按以下间隔检查并获取新论文。</p><label class="setting-label">检查间隔 <input v-model.number="settingsInterval" type="number" min="0.25" max="720" step="0.25" aria-label="自动检查间隔"> 小时</label><p class="hint">修改间隔调整下一次定时检查。关闭后停止论文的后台检查和下载，仍可手动获取。保留的栏目说明在启动时检查更新，已删除的可从获取往期取回。</p><p v-if="error" role="alert">{{error}}</p><template #footer><button @click="settingsOpen=false">取消</button><button class="primary" :disabled="settingsBusy" @click="saveInterval">保存间隔</button></template></ModalDialog>
 <ModalDialog v-if="historical" title="获取往期论文" wide :close-disabled="busy" @close="historical=false">
  <div class="archive-layout"><nav class="archive-tree" aria-label="往期年份月份"><button :class="{selected:archivePeriod===''}" @click="archivePeriod=''">全部年份</button><section v-for="year in archiveYears" :key="year"><button :class="{selected:archivePeriod===year}" @click="archivePeriod=year">{{year}} 年 <small>{{archive.filter(p=>p.publishedAt.startsWith(year)&&!p.downloaded).length}}</small></button><template v-if="archivePeriod.startsWith(year)"><button v-for="month in archiveMonths.filter(m=>m.startsWith(year))" :key="month" class="archive-month" :class="{selected:archivePeriod===month}" @click="archivePeriod=month">{{month.slice(5)}} 月</button></template></section></nav>
   <div class="archive-results"><div class="archive-top"><label><input type="checkbox" :checked="allChecked" :disabled="busy||!pendingPapers.length" @change="selectAll">全选当前筛选</label><small>{{pendingPapers.length}} 篇未获取</small></div><label v-for="p in pendingPapers" :key="p.id" class="archive-row"><input v-model="chosen" type="checkbox" :value="p.id" :disabled="busy"><span class="archive-titles" tabindex="0"><strong>{{p.titleZh}}</strong><span v-if="p.notice">栏目说明</span><span v-else>{{p.title}}</span><span v-if="!p.notice" class="abstract-tooltip" role="tooltip"><b>中文摘要</b><span>{{p.abstractZh||'暂无摘要'}}</span><b>Abstract</b><span>{{p.abstract||'No abstract available.'}}</span></span></span></label><p v-if="!pendingPapers.length" class="hint">当前年份或月份的论文均已获取。</p><label class="obtained-toggle"><input v-model="showObtained" type="checkbox">显示已获取 {{archivePapers.length-pendingPapers.length}} 篇</label><template v-if="showObtained"><label v-for="p in archivePapers.filter(p=>p.downloaded)" :key="p.id" class="archive-row obtained"><input type="checkbox" disabled checked><span class="archive-titles"><strong>{{p.titleZh}} · 已获取</strong><span>{{p.title}}</span></span></label></template></div>
  </div><p class="hint">已选 {{selectedPapers.length}} 篇 · 约 {{bytesLabel(downloadBytes)}}。跨月份的勾选保留，已获取内容不会重复下载。</p><p v-if="progress||error" role="status">{{error||progress}}</p><template #footer><button v-if="busy" @click="controller?.abort()">取消下载</button><button v-else @click="historical=false">关闭</button><button class="primary" :disabled="busy||!selectedPapers.length" @click="getPapers(selectedPapers.map(p=>p.id))">获取已选 {{selectedPapers.length}} 篇</button></template>
 </ModalDialog>
 <ModalDialog v-if="folderOpen" title="新建收藏夹" :close-disabled="busy" @close="folderOpen=false"><label class="setting-label">名称 <input v-model="folderName" maxlength="80" aria-label="收藏夹名称" @keyup.enter="folderName.trim()&&createFolder()"></label><p class="hint">{{source==='local'?(papers.web?'在当前论文库下创建同名子文件夹。':'将在本地论文根文件夹下创建同名子文件夹。'):'收藏夹仅用于整理服务器推荐，与个人 PDF 文件夹分开。'}}</p><p v-if="error" role="alert">{{error}}</p><template #footer><button :disabled="busy" @click="folderOpen=false">取消</button><button class="primary" :disabled="busy||!folderName.trim()" @click="createFolder">创建</button></template></ModalDialog>
 <ModalDialog v-if="moveOpen" :title="source==='local'?'整理 PDF':'收藏推荐论文'" :close-disabled="busy" @close="moveOpen=false"><label class="setting-label">放入 <select v-model="destinationFolder" aria-label="目标收藏夹"><option value="">{{source==='local'?'根文件夹':'未收藏'}}</option><option v-for="f in folders" :key="f" :value="f">{{f}}</option></select></label><p class="hint">{{source==='local'?'将移动本地库内的实际 PDF，原导入来源不变。已有批注跟随内容保留。':'仅更改推荐论文的本机收藏位置。'}}</p><p v-if="error" role="alert">{{error}}</p><template #footer><button :disabled="busy" @click="moveOpen=false">取消</button><button class="primary" :disabled="busy" @click="move">确定</button></template></ModalDialog>
 <ModalDialog v-if="trashOpen" title="论文回收站" :close-disabled="busy" @close="trashOpen=false"><p class="hint">恢复到原文件夹，原有批注保留。工作区结束前请导出需要长期保留的文件。</p><p v-if="!trashItems.length">回收站为空。</p><div v-for="item in trashItems" :key="item.id" class="archive-top"><span>{{item.title}}</span><button :disabled="busy" @click="restoreTrash(item.id)">恢复</button></div><p v-if="error" role="alert">{{error}}</p><template #footer><button :disabled="busy" @click="trashOpen=false">关闭</button></template></ModalDialog>
 <ModalDialog v-if="importOpen" title="导入本地 PDF" :close-disabled="busy" @close="importOpen=false"><label class="setting-label">存入 <select v-model="destinationFolder" aria-label="导入收藏夹"><option value="">根文件夹</option><option v-for="f in local.folders" :key="f" :value="f">{{f}}</option></select></label><p class="hint">接下来选择一份或多份 PDF，复制到所选文件夹。源文件保留，同名文件不会覆盖。</p><p v-if="error" role="alert">{{error}}</p><template #footer><button :disabled="busy" @click="importOpen=false">取消</button><button class="primary" :disabled="busy" @click="importPdfs">选择 PDF</button></template></ModalDialog>
 <ModalDialog v-if="deleteTarget" title="删除收藏夹" :close-disabled="busy" @close="deleteTarget=null"><p>删除收藏夹：<strong>{{deleteTarget.folder}}</strong></p><p class="hint">{{deleteTarget.source==='local'?'内部所有文件和子文件夹将移到上一级，PDF 及批注保留。遇到同名文件或文件夹时停止操作，请先处理重名项目。':'论文将回到未收藏，已下载的原文、译文、解读和批注均保留。'}}</p><p v-if="error" role="alert">{{error}}</p><template #footer><button :disabled="busy" @click="deleteTarget=null">取消</button><button class="primary" :disabled="busy" @click="deleteFolder">删除收藏夹并保留文件</button></template></ModalDialog>
 <ModalDialog v-if="citeOpen&&current" title="复制论文引用" @close="citeOpen=false"><label class="setting-label">引用格式<select v-model="citeStyle"><option v-for="style in citationStyles" :key="style" :value="style">{{style}}</option></select></label><textarea class="paper-citation" readonly :value="citationText" rows="7" aria-label="引用文本"/><p class="hint">引用指向原文固定版本，粘贴后请按学校或期刊要求设置排版。</p><p role="status">{{copyNotice}}</p><template #footer><button @click="citeOpen=false">关闭</button><button class="primary" @click="copyCitation">复制引用</button></template></ModalDialog>
 <Teleport to="body"><div v-if="paperMenu" ref="menuElement" role="menu" aria-label="论文操作" class="paper-context" :style="{left:paperMenu.x+'px',top:paperMenu.y+'px'}"><button role="menuitem" @click="preparePaperDelete">{{paperMenu.source==='server'?'删除本机副本':'移入回收站'}}</button></div></Teleport>
 <ModalDialog v-if="deletePaperTarget" :title="deletePaperTarget.notice?'删除栏目说明':deletePaperTarget.source==='server'?'删除论文副本':'移入回收站'" :close-disabled="busy" @close="deletePaperTarget=null"><p>{{deletePaperTarget.title}}</p><p class="hint">{{deletePaperTarget.notice?'删除本机栏目说明，批注保留。删除后不会自动获取，可从获取往期手动取回。':deletePaperTarget.source==='server'?'删除已下载的原文、译文与解读，批注保留。该论文不会被自动检查重新下载，可从获取往期手动取回。':(papers.web?'将这份 PDF 移入论文回收站，可在本页恢复。批注及导入前的源文件保留。':'将这份 PDF 从本地论文库移入系统回收站，批注保留。导入前的源文件不受影响；回收站不可用时保留文件。')}}</p><p v-if="error" role="alert">{{error}}</p><template #footer><button :disabled="busy" @click="deletePaperTarget=null">取消</button><button class="primary" :disabled="busy" @click="deletePaper">{{deletePaperTarget.source==='server'?'删除本机副本':'移入回收站'}}</button></template></ModalDialog>
</section>
